buggy.binomial_301_comparison:
import numba
import numpy as np

gen1 = np.random.default_rng(0)
gen2 = np.random.default_rng(0)

@numba.jit
def foo(g):
    return g.binomial(301, 0.1, 100)

try:
    result_jit = foo(gen1)
    result_py = foo.py_func(gen2)
    probe('binomial_301_0p1_100_jit', result_jit.tolist())
    probe('binomial_301_0p1_100_py', result_py.tolist())
except Exception as e:
    probe('binomial_301_0p1_100_error', str(e))

